11	  add(title: string): Todo {
12	    const trimmed = title.trim();
13	    if (!trimmed) throw new Error("Title is required");
14	    const todo = { id: this.nextId++, title: trimmed, done: false };
15	    this.todos.push(todo);
16	    return todo;
17	  }
18	
19	  toggle(id: number): Todo | undefined {
20	    const todo = this.todos.find((t) => t.id === id);
21	    if (todo) todo.done = !todo.done;
22	    return todo;
23	  }
24	
25	  remove(id: number): boolean {
26	    const index = this.todos.findIndex((t) => t.id === id);
27	    this.todos.splice(index, 1);
28	    return index !== -1;
29	  }
30	}
